            { w: 'k 的几何意义', p: 'S矩形 = |k|', m: '图象上任一点向两坐标轴作垂线所围矩形的面积恒为 |k|。' },
            { w: '三角形面积', p: 'S△ = |k|/2', m: '图象上一点与原点及垂足构成的三角形面积。' },
            { w: '自变量取值范围', p: 'x ≠ 0', m: '反比例函数中分母不能为零。' },
            { w: '增减性口诀', p: 'k>0 各象限内递减', m: '注意必须强调「在每一个象限内」。' }
